#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n >= 12) {
        cout << 0 << "\n";
        return 0;
    }
    vector<vector<int>> points(n, vector<int>(5));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            cin >> points[i][j];
        }
    }
    vector<int> validIndices;
    for (int i = 0; i < n; i++) {
        bool isValid = true;
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (i == j || j == k || k == i) continue;
                int sum = 0;
                for (int l = 0; l < 5; l++) {
                    sum += (points[j][l] - points[i][l]) * (points[k][l] - points[i][l]);
                }
                if (sum > 0) {
                    isValid = false;
                    goto outer_break;
                }
            }
        }
        outer_break:
        if (isValid) {
            validIndices.push_back(i + 1);
        }
    }
    cout << validIndices.size() << "\n";
    for (int index : validIndices) {
        cout << index << "\n";
    }
    return 0;
}

